import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.ktMMbWgA.js";const v=JSON.parse('{"title":"第 2 讲 · 经典 AI 的兴衰 — 符号、搜索、专家系统 · 参考","description":"","frontmatter":{"title":"第 2 讲 · 经典 AI 的兴衰 — 符号、搜索、专家系统 · 参考","act":1,"kind":"refs","prev":{"text":"L01 · 你以为你在思考","link":"/lectures/L01-cognitive-biases/references"},"next":{"text":"L03 · 学习即优化","link":"/lectures/L03-learning-optimization/references"}},"headers":[],"relativePath":"lectures/L02-classical-ai/references.md","filePath":"lectures/L02-classical-ai/references.md","lastUpdated":null}'),t={name:"lectures/L02-classical-ai/references.md"};function i(n,s,d,c,f,p){return e(),r("div",null,[...s[0]||(s[0]=[l('<h1 id="第-2-讲-·-参考资料-—-经典-ai-的黄金年代" tabindex="-1">第 2 讲 · 参考资料 — 经典 AI 的黄金年代 <a class="header-anchor" href="#第-2-讲-·-参考资料-—-经典-ai-的黄金年代" aria-label="Permalink to &quot;第 2 讲 · 参考资料 — 经典 AI 的黄金年代&quot;">​</a></h1><blockquote><p>分级阅读清单。⭐⭐⭐ = 必读；⭐⭐ = 推荐；⭐ = 进阶 / 选读。 带 ✅ 的已收集到 <code>media/</code> 目录。</p></blockquote><blockquote><p><strong>Last Verified</strong>: 2026-05-04 (links and citations checked; replace this when re-verifying)</p></blockquote><hr><section class="ref-card"><h2 class="ref-card-title" id="经典论文-符号-ai-黄金年代">1. 经典论文（符号 AI 黄金年代）</h2><h3 class="ref-group" id="经典论文-符号-ai-黄金年代--搜索与博弈">搜索与博弈</h3><ol class="ref-list"><li class="ref-item" id="ref-S1-1"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://ieeexplore.ieee.org/document/4082128" target="_blank" rel="noopener">A Formal Basis for the Heuristic Determination of Minimum Cost Paths</a></div><div class="ref-links"><a class="ref-link" href="http://aima.eecs.berkeley.edu/~russell/papers/hnr.pdf" target="_blank" rel="noopener">PDF mirror</a></div><p class="ref-desc">A\\* 算法原始论文</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Hart, Nilsson, Raphael 1968</p></div></li><li class="ref-item" id="ref-S1-2"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://academic.oup.com/mind/article/LIX/236/433/986238" target="_blank" rel="noopener">Computing Machinery and Intelligence</a></div><div class="ref-links"><a class="ref-link" href="https://courses.cs.umbc.edu/471/papers/turing.pdf" target="_blank" rel="noopener">PDF</a></div><p class="ref-desc">图灵测试原文。&quot;Can machines think?&quot;</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Turing 1950</p></div></li><li class="ref-item" id="ref-S1-3"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.pi.infn.it/~carosi/chess/shannon.txt" target="_blank" rel="noopener">Programming a Computer for Playing Chess</a></div><p class="ref-desc">Minimax + 评估函数的奠基。所有棋类 AI 的祖先。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Claude Shannon 1950</p></div></li><li class="ref-item" id="ref-S1-4"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://researcher.watson.ibm.com/researcher/files/us-beygel/samuel-checkers.pdf" target="_blank" rel="noopener">Some Studies in Machine Learning Using the Game of Checkers</a></div><p class="ref-desc">&quot;Machine Learning&quot; 一词的起源。学习评估函数的雏形。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Arthur Samuel 1959</p></div></li><li class="ref-item" id="ref-S1-5"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.sciencedirect.com/science/article/pii/S0004370201001291" target="_blank" rel="noopener">Deep Blue</a></div><div class="ref-links"><a class="ref-link" href="https://www.researchgate.net/publication/220093871_Deep_Blue" target="_blank" rel="noopener">ResearchGate</a></div><p class="ref-desc">Deep Blue 系统论文。Minimax + Alpha-Beta + 专用硬件。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Campbell, Hoane, Hsu 2002</p></div></li><li class="ref-item" id="ref-S1-6"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www-cs-faculty.stanford.edu/~knuth/papers/alpha-beta.pdf" target="_blank" rel="noopener">Alpha-Beta Pruning: A Survey</a></div><p class="ref-desc">Alpha-Beta 剪枝的形式化分析。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Knuth &amp; Moore 1975</p></div></li><li class="ref-item" id="ref-S1-7"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://history.computer.org/pioneers/newell.html" target="_blank" rel="noopener">The Logic Theorist</a></div><p class="ref-desc">第一个 AI 程序，证明 Whitehead-Russell 《数学原理》定理。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Newell, Simon, Shaw 1956</p></div></li><li class="ref-item" id="ref-S1-8"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.rand.org/pubs/papers/P2257.html" target="_blank" rel="noopener">GPS, A Program That Simulates Human Thought</a></div><p class="ref-desc">General Problem Solver。&quot;想模仿人脑解题过程&quot;的尝试。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Newell &amp; Simon 1961</p></div></li><li class="ref-item" id="ref-S1-9"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://ai.stanford.edu/~nilsson/OnlinePubs-Nils/PublishedPapers/strips.pdf" target="_blank" rel="noopener">STRIPS: A New Approach to the Application of Theorem Proving to Problem Solving</a></div><p class="ref-desc">经典规划算法 STRIPS。L26 Agent planning 的祖先。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Fikes &amp; Nilsson 1971</p></div></li></ol><h3 class="ref-group" id="经典论文-符号-ai-黄金年代--专家系统与知识表示">专家系统与知识表示</h3><ol class="ref-list"><li class="ref-item" id="ref-S1-10"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://exhibits.stanford.edu/feigenbaum/catalog/gv663zk7286" target="_blank" rel="noopener">MYCIN: A Rule-Based Computer Program for Advising Physicians</a></div><p class="ref-desc">专家系统标杆，医疗诊断领域。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Shortliffe 1976</p></div></li><li class="ref-item" id="ref-S1-11"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.sciencedirect.com/science/article/abs/pii/000437029390068M" target="_blank" rel="noopener">DENDRAL: A Case Study of the First Expert System for Scientific Hypothesis Formation</a></div><p class="ref-desc">第一个商业化专家系统。化学结构分析。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Lindsay, Buchanan, Feigenbaum, Lederberg 1993</p></div></li><li class="ref-item" id="ref-S1-12"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://web.media.mit.edu/~minsky/papers/Frames/frames.html" target="_blank" rel="noopener">A Framework for Representing Knowledge</a></div><p class="ref-desc">&quot;Frames&quot; 概念的奠基。语义网络/对象-属性的祖先。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Marvin Minsky 1974</p></div></li><li class="ref-item" id="ref-S1-13"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://web.stanford.edu/class/linguist236/papers/quillian.pdf" target="_blank" rel="noopener">Semantic Memory</a></div><p class="ref-desc">语义网络的开山之作。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Quillian 1968</p></div></li><li class="ref-item" id="ref-S1-14"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.cambridge.org/core/books/description-logic-handbook/8DF6BF42E65A2BDB3CC4DD5BAFB5A22F" target="_blank" rel="noopener">The Description Logic Handbook</a></div><p class="ref-desc">OWL 本体论的形式基础。L23 Knowledge Graph 的根基。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Baader, Calvanese et al.</p></div></li><li class="ref-item" id="ref-S1-15"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-title">The Knowledge Acquisition Bottleneck</span></div><p class="ref-desc">&quot;知识获取瓶颈&quot;概念的提出，专家系统衰落的预言。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Feigenbaum 1977</p></div></li><li class="ref-item" id="ref-S1-16"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://dl.acm.org/doi/10.1145/219717.219745" target="_blank" rel="noopener">Cyc: A Large-Scale Investment in Knowledge Infrastructure</a></div><p class="ref-desc">Cyc 项目——人类历史最大的&quot;手工编码常识&quot;实验。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Lenat 1995</p></div></li></ol><h3 class="ref-group" id="经典论文-符号-ai-黄金年代--优化与进化算法">优化与进化算法</h3><ol class="ref-list"><li class="ref-item" id="ref-S1-17"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://mitpress.mit.edu/9780262581110/adaptation-in-natural-and-artificial-systems/" target="_blank" rel="noopener">Adaptation in Natural and Artificial Systems</a></div><p class="ref-desc">遗传算法奠基之作。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>John Holland 1975</p></div></li><li class="ref-item" id="ref-S1-18"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.science.org/doi/10.1126/science.220.4598.671" target="_blank" rel="noopener">Optimization by Simulated Annealing</a></div><p class="ref-desc">模拟退火原始论文。Science 顶刊。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Kirkpatrick, Gelatt, Vecchi 1983</p></div></li><li class="ref-item" id="ref-S1-19"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://ieeexplore.ieee.org/document/488968" target="_blank" rel="noopener">Particle Swarm Optimization</a></div><p class="ref-desc">PSO 原始论文。&quot;鸟群&quot;启发的优化算法。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Kennedy &amp; Eberhart 1995</p></div></li><li class="ref-item" id="ref-S1-20"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://arxiv.org/abs/1703.03864" target="_blank" rel="noopener">Evolution Strategies as a Scalable Alternative to Reinforcement Learning</a></div><p class="ref-desc">OpenAI 用 ES 训练 RL 任务。古老算法的现代复兴。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Salimans et al. 2017</p></div></li><li class="ref-item" id="ref-S1-21"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://link.springer.com/article/10.1023/A:1008202821328" target="_blank" rel="noopener">Differential Evolution: A Simple and Efficient Heuristic</a></div><p class="ref-desc">DE 算法。当代仍在使用的进化算法。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Storn &amp; Price 1997</p></div></li><li class="ref-item" id="ref-S1-22"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://mitpress.mit.edu/9780262042192/ant-colony-optimization/" target="_blank" rel="noopener">Ant Colony Optimization</a></div><p class="ref-desc">ACO/蚁群算法。Multi-agent 启发式。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">作者 / 年份：</span>Dorigo &amp; Stützle 2004</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="现代复兴-neuro-symbolic-ai-经典-ai-在-llm-时代的回归-2020-2026">2. 现代复兴：Neuro-Symbolic AI / 经典 AI 在 LLM 时代的回归 (2020–2026)</h2><p class="ref-prose">&gt; 这一节是本讲在 2024-2026 年的真实价值：经典 AI 不是&quot;死了&quot;，而是和神经网络融合，成为当代 AI 系统的核心组件。</p><ol class="ref-list"><li class="ref-item" id="ref-N1"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N1</span><a class="ref-title" href="https://arxiv.org/abs/2012.05876" target="_blank" rel="noopener">Neural-Symbolic Learning and Reasoning: A Survey and Interpretation</a></div><div class="ref-meta">Garcez, Lamb 2020 · 2020</div><p class="ref-desc">Neuro-Symbolic AI 综述。给&quot;为什么经典 AI 还活着&quot;提供学术语境。</p></div></li><li class="ref-item" id="ref-N2"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N2</span><a class="ref-title" href="https://www.darpa.mil/news-events/2018-09-07" target="_blank" rel="noopener">The Third Wave of AI</a></div><div class="ref-meta">DARPA AI Next · 2018</div><p class="ref-desc">DARPA 的 &quot;Third Wave&quot; 框架——把 neuro-symbolic 称为下一波 AI。</p></div></li><li class="ref-item" id="ref-N3"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N3</span><a class="ref-title" href="https://arxiv.org/abs/2305.10601" target="_blank" rel="noopener">Tree of Thoughts: Deliberate Problem Solving with Large Language Models</a></div><div class="ref-meta">Yao et al. · 2023</div><p class="ref-desc">把 A\\* / 树搜索套到 LLM 上。本讲&quot;搜索 + LLM&quot;的当代版本。</p></div></li><li class="ref-item" id="ref-N4"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N4</span><a class="ref-title" href="https://arxiv.org/abs/2308.09687" target="_blank" rel="noopener">Graph of Thoughts: Solving Elaborate Problems with Large Language Models</a></div><div class="ref-meta">Besta et al. · 2023</div><p class="ref-desc">ToT 之后的&quot;图搜索 + LLM&quot;扩展。</p></div></li><li class="ref-item" id="ref-N5"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N5</span><a class="ref-title" href="https://www.nature.com/articles/nature24270" target="_blank" rel="noopener"><strong>Mastering the Game of Go without Human Knowledge</strong> (AlphaGo Zero)</a></div><div class="ref-meta">Silver et al. (DeepMind) · 2017</div><p class="ref-desc">AlphaGo Zero。MCTS（经典 AI）+ 神经网络的合体。本讲&quot;为什么经典 AI 没死&quot;最有力证据。</p></div></li><li class="ref-item" id="ref-N6"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N6</span><a class="ref-title" href="https://www.nature.com/articles/s41586-023-06747-5" target="_blank" rel="noopener">AlphaGeometry: An Olympiad-Level Mathematical Reasoning System</a></div><div class="ref-meta">Trinh et al. (DeepMind) · 2024</div><div class="ref-links"><a class="ref-link" href="https://github.com/google-deepmind/alphageometry" target="_blank" rel="noopener">GitHub</a></div><p class="ref-desc">DeepMind 2024 年的 IMO 几何 AI。LLM 给候选 + 符号求解器验证。Neuro-symbolic 的标杆案例。</p></div></li><li class="ref-item" id="ref-N7"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N7</span><a class="ref-title" href="https://deepmind.google/discover/blog/ai-solves-imo-problems-at-silver-medal-level/" target="_blank" rel="noopener"><strong>AlphaProof and AlphaGeometry 2</strong> (IMO 2024 silver medal)</a></div><div class="ref-meta">DeepMind 2024 · 2024</div><p class="ref-desc">AI 在 IMO 拿银牌——核心仍是符号求解器（Lean）+ 神经搜索。</p></div></li><li class="ref-item" id="ref-N8"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N8</span><a class="ref-title" href="https://www.nature.com/articles/s41586-023-06924-6" target="_blank" rel="noopener">FunSearch: Mathematical discoveries from program search with large language models</a></div><div class="ref-meta">Romera-Paredes et al. (DeepMind) · 2024</div><p class="ref-desc">LLM 当作&quot;突变算子&quot;，进化算法选择。本讲遗传算法 + LLM 的合体。</p></div></li><li class="ref-item" id="ref-N9"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N9</span><a class="ref-title" href="https://arxiv.org/abs/2305.12295" target="_blank" rel="noopener">Logic-LM: Empowering Large Language Models with Symbolic Solvers for Faithful Logical Reasoning</a></div><div class="ref-meta">Pan et al. · 2023</div><p class="ref-desc">LLM → 一阶逻辑公式 → Z3 求解器。Hybrid pipeline 的标准范式。</p></div></li><li class="ref-item" id="ref-N10"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N10</span><a class="ref-title" href="https://arxiv.org/abs/2211.10435" target="_blank" rel="noopener">PAL: Program-aided Language Models</a></div><div class="ref-meta">Gao et al. · 2022</div><p class="ref-desc">LLM 写代码，Python 解释器执行。&quot;工具调用&quot;的雏形。L25 (Function Calling) 直接前驱。</p></div></li><li class="ref-item" id="ref-N11"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N11</span><a class="ref-title" href="https://arxiv.org/abs/2305.14992" target="_blank" rel="noopener"><strong>Reasoning with Language Model is Planning with World Model</strong> (RAP)</a></div><div class="ref-meta">Hao et al. · 2023</div><p class="ref-desc">MCTS + LLM 把推理转化为规划问题。</p></div></li><li class="ref-item" id="ref-N12"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N12</span><a class="ref-title" href="https://arxiv.org/abs/2105.02761" target="_blank" rel="noopener">Neural Algorithmic Reasoning</a></div><div class="ref-meta">Veličković, Blundell (DeepMind) · 2021</div><p class="ref-desc">&quot;教神经网络做经典算法&quot;——A\\*、Dijkstra、Bellman-Ford 都是目标。</p></div></li><li class="ref-item" id="ref-N13"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N13</span><a class="ref-title" href="https://arxiv.org/abs/2209.11142" target="_blank" rel="noopener"><strong>A Generalist Neural Algorithmic Learner</strong> (CLRS-30 benchmark)</a></div><div class="ref-meta">Ibarz et al. (DeepMind) · 2022</div><p class="ref-desc">CLRS 教科书算法的 30 项 benchmark。Transformer 学经典算法。</p></div></li><li class="ref-item" id="ref-N14"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N14</span><a class="ref-title" href="https://arxiv.org/abs/2305.15771" target="_blank" rel="noopener"><strong>On the Planning Abilities of Large Language Models</strong> (PlanBench)</a></div><div class="ref-meta">Valmeekam, Kambhampati et al. · 2023-24</div><p class="ref-desc">ASU 团队系统测试 LLM 在经典规划任务（Blocksworld、Logistics）上的表现——结果很差。</p></div></li><li class="ref-item" id="ref-N15"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N15</span><a class="ref-title" href="https://arxiv.org/abs/2208.14271" target="_blank" rel="noopener">Faithful Reasoning Using Large Language Models</a></div><div class="ref-meta">Creswell, Shanahan · 2022</div><p class="ref-desc">Selection-Inference framework。把推理拆成&quot;选+推&quot;两步。</p></div></li><li class="ref-item" id="ref-N16"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">N16</span><a class="ref-title" href="https://www.nature.com/articles/s41586-023-06747-5" target="_blank" rel="noopener">Solving Olympiad Geometry Without Human Demonstrations</a></div><div class="ref-meta">Trinh et al. (DeepMind) · 2024</div><p class="ref-desc">AlphaGeometry 完整论文版。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="经典书籍-仍是教科书圣经">3. 经典书籍（仍是教科书圣经）</h2><ol class="ref-list"><li class="ref-item" id="ref-S3-1"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="http://aima.cs.berkeley.edu/" target="_blank" rel="noopener">Artificial Intelligence: A Modern Approach (4th Ed.)</a></div><div class="ref-meta">Russell &amp; Norvig · 2020</div><div class="ref-links"><a class="ref-link" href="https://www.pearson.com/en-us/subject-catalog/p/artificial-intelligence-a-modern-approach/P200000003500/9780137505135" target="_blank" rel="noopener">Pearson</a></div><p class="ref-desc">AI 教科书圣经，Ch3-5 搜索，Ch7-9 知识表示，Ch10 规划。本讲所有内容的&quot;权威定义来源&quot;。</p></div></li><li class="ref-item" id="ref-S3-2"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://ai.stanford.edu/~nilsson/QAI/qai.pdf" target="_blank" rel="noopener">The Quest for Artificial Intelligence</a></div><div class="ref-meta">Nils Nilsson · 2009</div><p class="ref-desc">528 页，A\\* 发明者亲述 AI 史。<strong>完全免费</strong>。本讲历史叙事的最佳来源。</p></div></li><li class="ref-item" id="ref-S3-3"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.routledge.com/Machines-Who-Think-A-Personal-Inquiry-into-the-History-and-Prospects/McCorduck/p/book/9781568812052" target="_blank" rel="noopener">Machines Who Think (2nd ed.)</a></div><div class="ref-meta">Pamela McCorduck · 2004</div><p class="ref-desc">AI 叙事史，从达特茅斯到 21 世纪。</p></div></li><li class="ref-item" id="ref-S3-4"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://github.com/norvig/paip-lisp" target="_blank" rel="noopener">Paradigms of Artificial Intelligence Programming</a></div><div class="ref-meta">Peter Norvig · 1991</div><p class="ref-desc">&quot;经典 AI 是怎么写代码的&quot;——Lisp 实现 Eliza、GPS、Othello。Norvig 已开源。</p></div></li><li class="ref-item" id="ref-S3-5"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://archive.org/details/heuristicsintell00pear" target="_blank" rel="noopener">Heuristics: Intelligent Search Strategies</a></div><div class="ref-meta">Judea Pearl · 1984</div><p class="ref-desc">启发式搜索的形式分析。Pearl 后来转向贝叶斯网络。</p></div></li><li class="ref-item" id="ref-S3-6"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.cengage.com/c/expert-systems-principles-and-programming-4e-giarratano/9780534384470/" target="_blank" rel="noopener">Expert Systems: Principles and Programming</a></div><div class="ref-meta">Giarratano &amp; Riley · 2004</div><p class="ref-desc">专家系统技术细节，CLIPS 引擎实现。</p></div></li><li class="ref-item" id="ref-S3-7"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.simonandschuster.com/books/The-Society-of-Mind/Marvin-Minsky/9780671657130" target="_blank" rel="noopener">The Society of Mind</a></div><div class="ref-meta">Marvin Minsky · 1986</div><p class="ref-desc">Minsky 关于&quot;智能由很多简单 agent 组成&quot;的哲学专著。</p></div></li><li class="ref-item" id="ref-S3-8"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.basicbooks.com/titles/douglas-r-hofstadter/godel-escher-bach/9780465026562/" target="_blank" rel="noopener">Gödel, Escher, Bach: An Eternal Golden Braid</a></div><div class="ref-meta">Douglas Hofstadter · 1979</div><p class="ref-desc">普利策奖。&quot;智能能否从形式系统涌现&quot;——经典 AI 时代的哲学经典。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="视频与课程">4. 视频与课程</h2><ol class="ref-list"><li class="ref-item" id="ref-S4-1"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.imdb.com/title/tt0379296/" target="_blank" rel="noopener">Game Over: Kasparov and the Machine</a></div><div class="ref-meta">Documentary 2003 · 84 min</div><div class="ref-links"><a class="ref-link" href="https://search.bilibili.com/all?keyword=Kasparov+Deep+Blue" target="_blank" rel="noopener">Bilibili 搜索</a></div><p class="ref-desc">Deep Blue vs 卡斯帕罗夫纪录片。本讲&quot;Deep Blue&quot;片段的最佳来源。</p></div></li><li class="ref-item" id="ref-S4-2"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.youtube.com/watch?v=WXuK6gekU1Y" target="_blank" rel="noopener">AlphaGo — The Movie</a></div><div class="ref-meta">DeepMind / Greg Kohs · 90 min</div><p class="ref-desc">AlphaGo 纪录片。展示&quot;经典 AI（MCTS）+ 神经网络&quot;如何合体。</p></div></li><li class="ref-item" id="ref-S4-3"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://ocw.mit.edu/courses/6-034-artificial-intelligence-fall-2010/" target="_blank" rel="noopener">MIT 6.034: Artificial Intelligence (Patrick Winston)</a></div><div class="ref-meta">MIT OCW · 全季公开课</div><div class="ref-links"><a class="ref-link" href="https://www.youtube.com/watch?v=TjZBTDzGeGg" target="_blank" rel="noopener">YouTube</a></div><p class="ref-desc">Winston 是&quot;AI Knowledge&quot;教科书作者。第 4-7 讲覆盖搜索、约束传播、博弈树。<strong>经典必看</strong>。</p></div></li><li class="ref-item" id="ref-S4-4"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://inst.eecs.berkeley.edu/~cs188/" target="_blank" rel="noopener">UC Berkeley CS 188: Introduction to AI</a></div><div class="ref-meta">Klein, Abbeel et al. · 全季</div><div class="ref-links"><a class="ref-link" href="https://www.youtube.com/playlist?list=PLp6ek2hDcoNBC0CzAQA1QtfwepXQ8u8FU" target="_blank" rel="noopener">YouTube</a></div><p class="ref-desc">Pacman 项目作业。本讲所有动手代码的灵感来源。</p></div></li><li class="ref-item" id="ref-S4-5"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.redblobgames.com/pathfinding/a-star/introduction.html" target="_blank" rel="noopener">A\\* Pathfinding Tutorial</a></div><div class="ref-meta">Red Blob Games · 交互</div><p class="ref-desc">浏览器内交互式 A\\* 教程。讲座最强可视化辅助。</p></div></li><li class="ref-item" id="ref-S4-6"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.youtube.com/watch?v=lcb7-bC7eDQ" target="_blank" rel="noopener">The History of AI in 10 Minutes</a></div><div class="ref-meta">ColdFusion 2023 · 10 min</div><p class="ref-desc">AI 历史快速回顾</p></div></li><li class="ref-item" id="ref-S4-7"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.ted.com/talks/stuart_russell_3_principles_for_creating_safer_ai" target="_blank" rel="noopener">The Coming AI Revolutions (Stuart Russell)</a></div><div class="ref-meta">TED 2017 · 18 min</div><p class="ref-desc">Russell 教授的&quot;机器目标 = 人类福利&quot;原则。L34 Safety 的预读。</p></div></li><li class="ref-item" id="ref-S4-8"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.thethinkinggame.film/" target="_blank" rel="noopener">The Thinking Game (Hassabis &amp; DeepMind)</a></div><div class="ref-meta">Documentary 2024 · 100 min</div><p class="ref-desc">DeepMind 历史纪录片。覆盖 AlphaGo → AlphaFold → Gemini。</p></div></li><li class="ref-item" id="ref-S4-9"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.youtube.com/watch?v=9zfeTw-uFCw" target="_blank" rel="noopener">Genetic Algorithm Visualization</a></div><div class="ref-meta">The Coding Train · ~10 min</div><p class="ref-desc">遗传算法可视化（Daniel Shiffman 经典系列）。</p></div></li><li class="ref-item" id="ref-S4-10"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.youtube.com/results?search_query=simulated+annealing+TSP+visualization" target="_blank" rel="noopener">Solving Travelling Salesman with Simulated Annealing</a></div><div class="ref-meta">~10 min</div><p class="ref-desc">模拟退火可视化。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="博客-网页-经典必读">5. 博客 / 网页：经典必读</h2><ol class="ref-list"><li class="ref-item" id="ref-S5-1"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.redblobgames.com/pathfinding/a-star/introduction.html" target="_blank" rel="noopener">Introduction to A\\*</a></div><div class="ref-meta">Amit Patel (Red Blob Games)</div><p class="ref-desc">全网最佳 A\\* 入门。十几年来不断更新，交互可视化无敌。</p></div></li><li class="ref-item" id="ref-S5-2"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.redblobgames.com/pathfinding/a-star/implementation.html" target="_blank" rel="noopener">Implementation of A\\* (variations + tradeoffs)</a></div><div class="ref-meta">Red Blob Games</div><p class="ref-desc">A\\* 的工程实现细节。Open-set 数据结构、启发式选择、tie-breaking。</p></div></li><li class="ref-item" id="ref-S5-3"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="http://theory.stanford.edu/~amitp/GameProgramming/Heuristics.html" target="_blank" rel="noopener">Heuristics for Pathfinding</a></div><div class="ref-meta">Red Blob Games</div><p class="ref-desc">启发式函数选择的工程指南。</p></div></li><li class="ref-item" id="ref-S5-4"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="http://www.incompleteideas.net/IncIdeas/BitterLesson.html" target="_blank" rel="noopener">The Bitter Lesson</a></div><div class="ref-meta">Richard Sutton</div><p class="ref-desc">5 段话经典：所有用&quot;人类先验知识&quot;的 AI 方法，最终都被&quot;通用方法 + 算力&quot;打败。本讲&quot;为什么手工编程智能失败&quot;的最佳压缩。</p></div></li><li class="ref-item" id="ref-S5-5"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://en.wikipedia.org/wiki/AI_winter" target="_blank" rel="noopener">AI Winter (Wikipedia)</a></div><div class="ref-meta">Wikipedia</div><p class="ref-desc">AI 寒冬历史时间线，引用扎实。</p></div></li><li class="ref-item" id="ref-S5-6"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://plato.stanford.edu/entries/computer-science/" target="_blank" rel="noopener">Expert Systems (Stanford Encyclopedia)</a></div><div class="ref-meta">SEP</div><p class="ref-desc">哲学+技术综述。</p></div></li><li class="ref-item" id="ref-S5-7"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://users.ecs.soton.ac.uk/harnad/Papers/Harnad/harnad90.sgproblem.html" target="_blank" rel="noopener">The Symbol Grounding Problem</a></div><div class="ref-meta">Stevan Harnad 1990</div><p class="ref-desc">&quot;符号系统能否真的&#39;懂&#39;符号的意义&quot;——经典哲学难题。</p></div></li><li class="ref-item" id="ref-S5-8"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://norvig.com/chomsky.html" target="_blank" rel="noopener">Norvig: On Chomsky and the Two Cultures of Statistical Learning</a></div><div class="ref-meta">Peter Norvig 2011</div><p class="ref-desc">&quot;数据派 vs 规则派&quot;经典互喷。Chomsky 批判统计 ML，Norvig 反驳。</p></div></li><li class="ref-item" id="ref-S5-9"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.toptal.com/algorithms/simulated-annealing" target="_blank" rel="noopener">Simulated Annealing: A Visual Guide</a></div><div class="ref-meta">Toptal / Setosa</div><div class="ref-links"><a class="ref-link" href="https://setosa.io/ev/" target="_blank" rel="noopener">Setosa.io</a></div><p class="ref-desc">模拟退火可视化教程。</p></div></li><li class="ref-item" id="ref-S5-10"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://exhibits.stanford.edu/feigenbaum" target="_blank" rel="noopener">A History of MYCIN</a></div><div class="ref-meta">Stanford Stories</div><p class="ref-desc">Stanford 数字博物馆 MYCIN 项目档案。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="现代行业声音-2023-2026-经典-ai-还有用吗">6. 现代行业声音 (2023–2026): &quot;经典 AI 还有用吗？&quot;</h2><ol class="ref-list"><li class="ref-item" id="ref-I1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">I1</span><a class="ref-title" href="https://arxiv.org/abs/2002.06177" target="_blank" rel="noopener">The Next Decade in AI: Four Steps Towards Robust Artificial Intelligence</a></div><div class="ref-meta">Gary Marcus 2020 · 2020</div><p class="ref-desc">Marcus 的 hybrid AI 路线图。&quot;必须把符号系统加回来。&quot;</p></div></li><li class="ref-item" id="ref-I2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">I2</span><a class="ref-title" href="https://www.noemamag.com/deep-learning-alone-isnt-getting-us-to-human-like-ai/" target="_blank" rel="noopener">Deep Learning Alone Isn&#39;t Getting Us To Human-Like AI</a></div><div class="ref-meta">Marcus, Davis 2022 · 2022</div><p class="ref-desc">Marcus 在大众媒体上的 hybrid AI 论证。</p></div></li><li class="ref-item" id="ref-I3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">I3</span><a class="ref-title" href="https://research.ibm.com/blog/AI-neuro-symbolic-common-sense" target="_blank" rel="noopener">The neuro-symbolic AI breakthrough: A new way for machines to reason</a></div><div class="ref-meta">IBM Research blog · 2023</div><p class="ref-desc">IBM 路线：&quot;纯神经网络无法做常识推理&quot;。</p></div></li><li class="ref-item" id="ref-I4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">I4</span><a class="ref-title" href="https://deepmind.google/research/highlighted-research/" target="_blank" rel="noopener">Why DeepMind is using classical algorithms with neural nets</a></div><div class="ref-meta">DeepMind blogs · 22-25</div><p class="ref-desc">AlphaGeometry / AlphaProof / FunSearch 系列博客。</p></div></li><li class="ref-item" id="ref-I5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">I5</span><a class="ref-title" href="https://deepmind.google/discover/blog/welcome-to-the-era-of-experience/" target="_blank" rel="noopener">Sutton &amp; Silver: Welcome to the Era of Experience</a></div><div class="ref-meta">Silver, Sutton 2025 · 2025</div><p class="ref-desc">反向论证：&quot;纯监督学习时代结束，agent 通过和环境交互学习——这才是经典 RL/搜索的回归。&quot;</p></div></li><li class="ref-item" id="ref-I6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">I6</span><a class="ref-title" href="https://www.nytimes.com/2023/06/03/technology/gary-marcus-ai-future.html" target="_blank" rel="noopener"><strong>The AI Researcher Who Bet Against Deep Learning</strong> (Marcus profile)</a></div><div class="ref-meta">NY Times · 2023</div><p class="ref-desc">Marcus 个人故事 + hybrid AI 视角。</p></div></li><li class="ref-item" id="ref-I7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">I7</span><a class="ref-title" href="https://ai.meta.com/blog/yann-lecun-ai-model-i-jepa/" target="_blank" rel="noopener">Yann LeCun on JEPA and World Models</a></div><div class="ref-meta">Meta AI blog · 2022-25</div><p class="ref-desc">LeCun 路线：&quot;LLM 不行，需要新架构 + 隐式世界模型。&quot;</p></div></li><li class="ref-item" id="ref-I8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">I8</span><a class="ref-title" href="https://arxiv.org/abs/2402.04210" target="_blank" rel="noopener">On the Self-Verification Limitations of LLMs</a></div><div class="ref-meta">Kambhampati group · 2024</div><p class="ref-desc">ASU 教授系列：LLM 不能做经典规划，必须用 PDDL 求解器辅助。</p></div></li><li class="ref-item" id="ref-I9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">I9</span><span class="ref-title">OpenAI&#39;s o1/o3 reasoning models: are they &quot;search&quot;?</span></div><div class="ref-meta">community essays / Karpathy etc. · 2024-25</div><p class="ref-desc">行业讨论：&quot;o1 内部就是 MCTS-like 搜索&quot;——经典 AI 的隐式回归。</p></div></li><li class="ref-item" id="ref-I10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">I10</span><a class="ref-title" href="https://arxiv.org/abs/2212.08073" target="_blank" rel="noopener">Anthropic&#39;s Constitutional AI as rule-based safety layer</a></div><div class="ref-meta">Anthropic 2022 · 2022</div><p class="ref-desc">Constitutional AI = 规则编程的现代版本，叠加在神经模型上。</p></div></li><li class="ref-item" id="ref-I11"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">I11</span><span class="ref-title">Why Knowledge Graphs Are the Missing Link Between LLMs and Reliable AI</span></div><div class="ref-meta">2024</div><p class="ref-desc">KG 厂商立场，但论证扎实：LLM 幻觉 → 用 KG 做约束。</p></div></li><li class="ref-item" id="ref-I12"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">I12</span><a class="ref-title" href="https://news.stanford.edu/stories/2023/09/doug-lenat-pioneer-ai-cyc-dies-72" target="_blank" rel="noopener">Doug Lenat (1950-2023) obituary + Cyc reflections</a></div><div class="ref-meta">2023</div><p class="ref-desc">Cyc 创始人去世。50 年&quot;手工编码常识&quot;实验的盖棺定论文。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="代码仓库">7. 代码仓库</h2><ol class="ref-list"><li class="ref-item" id="ref-S7-1"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://github.com/aimacode/aima-python" target="_blank" rel="noopener">aima-python</a></div><p class="ref-desc">Russell &amp; Norvig 教科书所有算法的官方 Python 实现。本讲所有经典算法的&quot;参考实现&quot;。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">语言：</span>Python</p></div></li><li class="ref-item" id="ref-S7-2"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="http://ai.berkeley.edu/project_overview.html" target="_blank" rel="noopener">UC Berkeley CS188 Pacman Projects</a></div><p class="ref-desc">Pacman 用 BFS/DFS/A\\*/Minimax/RL 求解。最好的&quot;动手作业&quot;。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">语言：</span>Python</p></div></li><li class="ref-item" id="ref-S7-3"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://github.com/jrialland/python-astar" target="_blank" rel="noopener">python-astar</a></div><p class="ref-desc">A\\* 参考实现，pip 可装。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">语言：</span>Python</p></div></li><li class="ref-item" id="ref-S7-4"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://networkx.org/" target="_blank" rel="noopener">networkx</a></div><div class="ref-links"><a class="ref-link" href="https://github.com/networkx/networkx" target="_blank" rel="noopener">GitHub</a></div><p class="ref-desc">图算法标准库。BFS/DFS/Dijkstra/A\\* 都有。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">语言：</span>Python</p></div></li><li class="ref-item" id="ref-S7-5"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://github.com/nilp0inter/experta" target="_blank" rel="noopener">pyknow / experta</a></div><p class="ref-desc">Python 规则引擎库（CLIPS 风格）。专家系统现代实现。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">语言：</span>Python</p></div></li><li class="ref-item" id="ref-S7-6"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://github.com/DEAP/deap" target="_blank" rel="noopener">DEAP</a></div><p class="ref-desc">Python 进化算法框架。GA/ES/PSO 都有。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">语言：</span>Python</p></div></li><li class="ref-item" id="ref-S7-7"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://github.com/Z3Prover/z3" target="_blank" rel="noopener">Z3 Theorem Prover</a></div><p class="ref-desc">Microsoft Research 的 SMT 求解器。Logic-LM、AlphaProof 内部用的就是它。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">语言：</span>Python/C++</p></div></li><li class="ref-item" id="ref-S7-8"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://github.com/asanchez75/opencyc" target="_blank" rel="noopener">OpenCyc archive</a></div><p class="ref-desc">Lenat 的&quot;常识知识库&quot;开源存档。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">语言：</span>Lisp</p></div></li><li class="ref-item" id="ref-S7-9"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://github.com/Wikidata/Wikidata-Toolkit" target="_blank" rel="noopener">Wikidata Toolkit</a></div><p class="ref-desc">现代最大的开源结构化知识库的 SDK。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">语言：</span>Java/Python</p></div></li><li class="ref-item" id="ref-S7-10"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://ccl.northwestern.edu/netlogo/" target="_blank" rel="noopener">NetLogo</a></div><p class="ref-desc">Multi-agent 模拟。蚁群算法、Boids、谢林模型经典实现都有。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">语言：</span>NetLogo</p></div></li><li class="ref-item" id="ref-S7-11"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.swi-prolog.org/" target="_blank" rel="noopener">SWI-Prolog</a></div><p class="ref-desc">逻辑编程语言。&quot;经典 AI 编程&quot;的母语。教学价值巨大。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">语言：</span>Prolog</p></div></li><li class="ref-item" id="ref-S7-12"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><a class="ref-title" href="https://www.fast-downward.org/" target="_blank" rel="noopener">Fast Downward Planner</a></div><p class="ref-desc">STRIPS/PDDL 经典规划求解器。AI Planning Competition 默认 baseline。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">语言：</span>C++</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="主流-ai-planning-knowledge-graph-行业实践">8. 主流 AI Planning / Knowledge Graph 行业实践</h2><ol class="ref-list"><li class="ref-item" id="ref-KG1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">KG1</span><a class="ref-title" href="https://blog.google/products/search/introducing-knowledge-graph-things-not/" target="_blank" rel="noopener">Google Knowledge Graph</a></div><div class="ref-meta">Google</div><p class="ref-desc">2012 年 Google 把搜索从&quot;字符串&quot;升级到&quot;事物&quot;。本讲&quot;知识图谱产业版&quot;的开端。</p></div></li><li class="ref-item" id="ref-KG2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">KG2</span><a class="ref-title" href="https://www.wikidata.org/" target="_blank" rel="noopener">Wikidata</a></div><div class="ref-meta">Wikimedia</div><p class="ref-desc">当前最大的开放结构化知识库。1.1 亿+ 条目。</p></div></li><li class="ref-item" id="ref-KG3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">KG3</span><a class="ref-title" href="https://www.dbpedia.org/" target="_blank" rel="noopener">DBpedia</a></div><div class="ref-meta">DBpedia community</div><p class="ref-desc">从 Wikipedia infobox 抽取的结构化知识。</p></div></li><li class="ref-item" id="ref-KG4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">KG4</span><a class="ref-title" href="https://openalex.org/" target="_blank" rel="noopener"><strong>OpenAlex</strong> (formerly Microsoft Academic Graph)</a></div><div class="ref-meta">OurResearch</div><p class="ref-desc">2.4 亿+ 学术论文的知识图谱。Microsoft 2021 关闭后由 OurResearch 继承。</p></div></li><li class="ref-item" id="ref-KG5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">KG5</span><a class="ref-title" href="https://schema.org/" target="_blank" rel="noopener">Schema.org</a></div><div class="ref-meta">Google/Bing/Yahoo/Yandex</div><p class="ref-desc">Web 网页的结构化数据标准。</p></div></li><li class="ref-item" id="ref-KG6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">KG6</span><a class="ref-title" href="https://neo4j.com/" target="_blank" rel="noopener">Neo4j / NebulaGraph / TigerGraph</a></div><div class="ref-links"><a class="ref-link" href="https://www.nebula-graph.io/" target="_blank" rel="noopener">nebula-graph.io</a></div><p class="ref-desc">图数据库。当代 KG 工程的存储底座。</p></div></li><li class="ref-item" id="ref-P1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P1</span><a class="ref-title" href="https://www.fast-downward.org/" target="_blank" rel="noopener">Fast Downward Planner</a></div><div class="ref-meta">Univ. Basel + Linköping</div><p class="ref-desc">经典规划求解器，IPC 历届冠军。</p></div></li><li class="ref-item" id="ref-P2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P2</span><a class="ref-title" href="https://planning.wiki/" target="_blank" rel="noopener">PDDL (Planning Domain Definition Language)</a></div><div class="ref-meta">International Planning Competition</div><p class="ref-desc">经典规划任务的标准描述语言。LLM + PDDL 是 2024-25 年热点。</p></div></li><li class="ref-item" id="ref-P3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P3</span><a class="ref-title" href="https://github.com/karthikv792/LLMs-Planning" target="_blank" rel="noopener">Plan-Bench (LLMs-Planning)</a></div><div class="ref-meta">Kambhampati group</div><div class="ref-links"><a class="ref-link" href="https://arxiv.org/abs/2206.10498" target="_blank" rel="noopener">paper</a></div><p class="ref-desc">LLM 在经典规划任务上的 benchmark。L26 Agent 的预读。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="中文与本土资源">9. 中文与本土资源</h2><ol class="ref-list"><li class="ref-item" id="ref-Z1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">Z1</span><span class="ref-title">AIMA 中译本：人工智能：现代方法（第 4 版）</span></div><div class="ref-meta">清华大学出版社</div><p class="ref-desc">Russell &amp; Norvig 中文版。</p></div></li><li class="ref-item" id="ref-Z2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">Z2</span><span class="ref-title">《人工智能简史》</span></div><div class="ref-meta">尼克 2017</div><p class="ref-desc">中文 AI 史最佳通俗读物。覆盖符号派/连接派之争。</p></div></li><li class="ref-item" id="ref-Z3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">Z3</span><span class="ref-title">《知识图谱：方法、实践与应用》</span></div><div class="ref-meta">王昊奋等</div><p class="ref-desc">中文 KG 工程实践第一本。</p></div></li><li class="ref-item" id="ref-Z4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">Z4</span><a class="ref-title" href="http://openkg.cn/" target="_blank" rel="noopener">OpenKG 开放知识图谱</a></div><div class="ref-meta">中国 KG 社区</div><p class="ref-desc">中文知识图谱开放数据集合。</p></div></li><li class="ref-item" id="ref-Z5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">Z5</span><a class="ref-title" href="http://kw.fudan.edu.cn/cndbpedia/" target="_blank" rel="noopener">CN-DBpedia / zhishi.me</a></div><div class="ref-meta">复旦/上海交大</div><div class="ref-links"><a class="ref-link" href="http://zhishi.me/" target="_blank" rel="noopener">zhishi.me</a></div><p class="ref-desc">中文百科结构化知识库。</p></div></li><li class="ref-item" id="ref-Z6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">Z6</span><a class="ref-title" href="https://search.bilibili.com/all?keyword=A%2A+算法+可视化" target="_blank" rel="noopener">**A\\* 算法可视化（B 站）**</a></div><div class="ref-meta">多 UP 主</div><p class="ref-desc">中文动画讲解。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="课程后续讲座中-经典-ai-回归-的重点呼应">10. 课程后续讲座中&quot;经典 AI 回归&quot;的重点呼应</h2><ol class="ref-list"><li class="ref-item" id="ref-S10-1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"></span></div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">后续讲：</span>L17 (RL)</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">经典 AI 呼应点：</span>MCTS（蒙特卡洛树搜索）= 本讲 Minimax + Sampling 的现代版本。AlphaGo 的核心。</p></div></li><li class="ref-item" id="ref-S10-2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"></span></div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">后续讲：</span>L20 (推理模型)</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">经典 AI 呼应点：</span>OpenAI o1/o3 的&quot;思考时间&quot;内部很可能就是树搜索 + reward model。</p></div></li><li class="ref-item" id="ref-S10-3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"></span></div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">后续讲：</span>L23 (Embedding)</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">经典 AI 呼应点：</span>用向量替代符号——知识表示的连续化。</p></div></li><li class="ref-item" id="ref-S10-4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"></span></div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">后续讲：</span>L24 (RAG)</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">经典 AI 呼应点：</span>RAG = &quot;向量检索 + 知识库&quot;——知识获取瓶颈的工程解。</p></div></li><li class="ref-item" id="ref-S10-5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"></span></div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">后续讲：</span>L25 (Function Calling)</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">经典 AI 呼应点：</span>LLM 调用外部工具 = &quot;把符号求解器当成 LLM 的子程序&quot;。</p></div></li><li class="ref-item" id="ref-S10-6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"></span></div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">后续讲：</span>L26 (Agent)</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">经典 AI 呼应点：</span>ReAct / Tree-of-Thought / Plan-and-Execute = 经典规划算法 + LLM 混搭。</p></div></li><li class="ref-item" id="ref-S10-7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"></span></div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">后续讲：</span>L33 (Embodied AI)</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">经典 AI 呼应点：</span>经典运动规划（A\\*、RRT）+ 神经控制器是当代机器人的标准栈。</p></div></li><li class="ref-item" id="ref-S10-8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"></span></div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">后续讲：</span>L34 (Safety)</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">经典 AI 呼应点：</span>Constitutional AI / Guardrails = 在神经网络外面套规则的现代专家系统。</p></div></li></ol></section>',14)])])}const h=a(t,[["render",i]]);export{v as __pageData,h as default};
